220:   window.on('close', event => {
221:     if (quitting || closeApproved) return;
222:     event.preventDefault();
223:     hideMainWindowToTray();
224:   });
225:   window.on('closed', () => { mainWindow = null; });
226: 
227:   await window.loadURL(`${address.url}/`);
228:   logStartup(`window:loaded ${address.url}/`);
229:   return window;
230: }
