6: class BackendProcess {
7:   constructor({ appRoot, dataRoot, onUnexpectedExit }) {
8:     this.appRoot = appRoot;
9:     this.dataRoot = dataRoot;
10:     this.onUnexpectedExit = onUnexpectedExit;
11:     this.child = null;
12:     this.address = null;
13:     this.sessionToken = '';
14:     this.stopping = false;
15:   }
