17:   start() {
18:     if (this.child) return Promise.resolve(this.address);
19:     this.stopping = false;
20:     this.sessionToken = randomBytes(32).toString('hex');
21:     const packaged = this.appRoot.endsWith('.asar');
22:     const runtimeRoot = packaged ? path.dirname(this.appRoot) : this.appRoot;
23:     const entry = packaged
24:       ? path.join(runtimeRoot, 'app.asar.unpacked', 'backend', 'server.js')
25:       : path.join(this.appRoot, 'backend', 'server.js');
26:     console.log(`[backend] Starting local service from ${entry}`);
27:     const childEnv = {
28:       ...process.env,
29:       NODE_ENV: 'production',
30:       HOSTNAME: '127.0.0.1',
31:       PORT: '0',
32:       NOVA_TASK_DB: path.join(this.dataRoot, 'data', 'tasks.sqlite'),
33:       NOVA_IMAGE_DIR: path.join(this.dataRoot, 'runtime', 'task-images'),
34:       NOVA_DESKTOP_SESSION_TOKEN: this.sessionToken,
35:       NOVA_STATIC_DIR: path.join(this.appRoot, 'frontend', 'out'),
36:       PROMPT_GALLERY_MODE: '1',
37:     };
38:     if (packaged) childEnv.NOVA_DESKTOP_MODULE_ROOT = this.appRoot;
39:     const child = packaged
40:       ? utilityProcess.fork(entry, [], {
41:           cwd: runtimeRoot,
42:           serviceName: 'AIOSS Image Local Service',
43:           stdio: 'pipe',
44:           env: childEnv,
45:         })
46:       : spawn(process.env.NODE || 'node', [entry], {
47:           cwd: runtimeRoot,
48:           stdio: ['pipe', 'pipe', 'pipe'],
49:           env: childEnv,
50:         });
51:     this.child = child;
52:     child.stdout?.on('data', chunk => process.stdout.write(`[backend] ${chunk}`));
53:     child.stderr?.on('data', chunk => process.stderr.write(`[backend] ${chunk}`));
54: 
55:     return new Promise((resolve, reject) => {
56:       const timeout = setTimeout(() => {
57:         reject(new Error('本地服务启动超时'));
58:         child.kill();
59:       }, 30_000);
60:       const readyPattern = /^AIOSS Image server ready on http:\/\/(?:localhost|127\.0\.0\.1):(\d+)/m;
61:       let stdoutBuffer = '';
62:       const onMessage = message => {
63:         if (message?.type === 'ready') {
64:           clearTimeout(timeout);
65:           this.address = message;
66:           resolve(message);
67:         } else if (message?.type === 'error') {
68:           clearTimeout(timeout);
69:           reject(new Error(message.message || '本地服务启动失败'));
70:         }
71:       };
72:       const onReadyLine = chunk => {
73:         stdoutBuffer = `${stdoutBuffer}${chunk.toString('utf8')}`.slice(-4096);
74:         const match = readyPattern.exec(stdoutBuffer);
75:         if (!match) return;
76:         clearTimeout(timeout);
77:         const address = { host: '127.0.0.1', port: Number(match[1]), url: `http://127.0.0.1:${match[1]}` };
78:         this.address = address;
79:         resolve(address);
80:       };
81:       if (packaged) child.on('message', onMessage);
82:       else child.stdout?.on('data', onReadyLine);
83:       child.once('exit', code => {
84:         clearTimeout(timeout);
85:         const unexpected = !this.stopping;
86:         this.child = null;
87:         this.address = null;
88:         if (unexpected) {
89:           reject(new Error(`本地服务异常退出，代码 ${code}`));
90:           this.onUnexpectedExit?.(code);
91:         }
92:       });
93:     });
94:   }
