1: const { createHash } = require('node:crypto');
2: const fs = require('node:fs');
3: const path = require('node:path');
4: 
5: const FILE_NAMESPACES = new Set(['history', 'assets', 'agent', 'canvas', 'cache']);
6: const ID_PATTERN = /^[A-Za-z0-9._:-]{1,240}$/;
7: 
8: function extensionFor(mimeType) {
9:   const normalized = String(mimeType || '').toLowerCase();
10:   if (normalized.includes('jpeg')) return '.jpg';
11:   if (normalized.includes('png')) return '.png';
12:   if (normalized.includes('webp')) return '.webp';
13:   if (normalized.includes('gif')) return '.gif';
14:   if (normalized.includes('avif')) return '.avif';
15:   return '.bin';
16: }
17: 
18: class FileStore {
19:   constructor(db, rootPath) {
20:     this.db = db;
21:     this.rootPath = path.resolve(rootPath);
22:     fs.mkdirSync(this.rootPath, { recursive: true });
23:     for (const namespace of FILE_NAMESPACES) fs.mkdirSync(path.join(this.rootPath, namespace), { recursive: true });
24:   }
25: 
26:   validate(namespace, id) {
27:     if (!FILE_NAMESPACES.has(namespace)) throw new Error(`Unsupported file namespace: ${namespace}`);
28:     if (!ID_PATTERN.test(id)) throw new Error('Invalid file id');
29:   }
30: 
31:   resolveRelative(relativePath) {
32:     const resolved = path.resolve(this.rootPath, relativePath);
33:     const prefix = `${this.rootPath}${path.sep}`;
34:     if (!resolved.startsWith(prefix)) throw new Error('Stored file path escapes the data directory');
35:     return resolved;
36:   }
37: 
38:   write(namespace, id, data, mimeType = 'application/octet-stream') {
39:     this.validate(namespace, id);
40:     const buffer = Buffer.isBuffer(data) ? data : Buffer.from(data);
41:     const sha256 = createHash('sha256').update(buffer).digest('hex');
42:     const idHash = createHash('sha256').update(`${namespace}\0${id}`).digest('hex');
43:     const relativePath = path.join(namespace, `${idHash}-${sha256.slice(0, 16)}${extensionFor(mimeType)}`);
44:     const finalPath = this.resolveRelative(relativePath);
45:     const tempPath = `${finalPath}.tmp-${process.pid}-${Date.now()}`;
46:     const previous = this.db.prepare('SELECT relative_path FROM stored_files WHERE namespace = ? AND id = ?').get(namespace, id);
47:     const now = new Date().toISOString();
48:     const finalAlreadyExists = fs.existsSync(finalPath);
49: 
50:     if (!finalAlreadyExists) fs.writeFileSync(tempPath, buffer, { flag: 'wx' });
51:     try {
52:       if (!finalAlreadyExists) fs.renameSync(tempPath, finalPath);
53:       this.db.prepare(`
54:         INSERT INTO stored_files (
55:           namespace, id, relative_path, mime_type, size_bytes, sha256,
56:           created_at, updated_at, last_accessed_at
57:         ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
58:         ON CONFLICT(namespace, id) DO UPDATE SET
59:           relative_path = excluded.relative_path,
60:           mime_type = excluded.mime_type,
61:           size_bytes = excluded.size_bytes,
62:           sha256 = excluded.sha256,
63:           updated_at = excluded.updated_at,
64:           last_accessed_at = excluded.last_accessed_at
65:       `).run(namespace, id, relativePath, mimeType, buffer.length, sha256, now, now, now);
66:     } catch (error) {
67:       try { fs.rmSync(tempPath, { force: true }); } catch { /* ignore */ }
68:       if (!finalAlreadyExists) {
69:         try { fs.rmSync(finalPath, { force: true }); } catch { /* ignore */ }
70:       }
71:       throw error;
72:     }
73: 
74:     if (previous?.relative_path && previous.relative_path !== relativePath) {
75:       try { fs.rmSync(this.resolveRelative(previous.relative_path), { force: true }); } catch { /* ignore */ }
76:     }
77:     return { id, namespace, mimeType, sizeBytes: buffer.length, sha256 };
78:   }
79: 
80:   read(namespace, id) {
81:     this.validate(namespace, id);
82:     const row = this.db.prepare(`
83:       SELECT relative_path, mime_type, size_bytes, sha256
84:       FROM stored_files WHERE namespace = ? AND id = ?
85:     `).get(namespace, id);
86:     if (!row) return null;
87:     const filePath = this.resolveRelative(row.relative_path);
88:     if (!fs.existsSync(filePath)) return null;
89:     this.db.prepare('UPDATE stored_files SET last_accessed_at = ? WHERE namespace = ? AND id = ?')
90:       .run(new Date().toISOString(), namespace, id);
91:     return {
92:       id,
93:       namespace,
94:       mimeType: row.mime_type,
95:       sizeBytes: row.size_bytes,
96:       sha256: row.sha256,
97:       data: fs.readFileSync(filePath),
98:     };
99:   }
100: 
101:   list(namespace) {
102:     if (!FILE_NAMESPACES.has(namespace)) throw new Error(`Unsupported file namespace: ${namespace}`);
103:     return this.db.prepare(`
104:       SELECT id, mime_type, size_bytes, sha256, created_at, updated_at, last_accessed_at
105:       FROM stored_files WHERE namespace = ? ORDER BY updated_at DESC
106:     `).all(namespace).map(row => ({
107:       id: row.id,
108:       namespace,
109:       mimeType: row.mime_type,
110:       sizeBytes: row.size_bytes,
111:       sha256: row.sha256,
112:       createdAt: row.created_at,
113:       updatedAt: row.updated_at,
114:       lastAccessedAt: row.last_accessed_at,
115:     }));
116:   }
117: 
118:   delete(namespace, id) {
119:     this.validate(namespace, id);
120:     const row = this.db.prepare('SELECT relative_path FROM stored_files WHERE namespace = ? AND id = ?').get(namespace, id);
121:     this.db.prepare('DELETE FROM stored_files WHERE namespace = ? AND id = ?').run(namespace, id);
122:     if (row?.relative_path) {
123:       try { fs.rmSync(this.resolveRelative(row.relative_path), { force: true }); } catch { /* ignore */ }
124:     }
125:   }
