127:   cleanup() {
128:     const referenced = new Set(this.db.prepare('SELECT relative_path FROM stored_files').all().map(row => path.normalize(row.relative_path)));
129:     let removed = 0;
130:     for (const namespace of FILE_NAMESPACES) {
131:       const directory = path.join(this.rootPath, namespace);
