427:     const cached = this.getStorage().files.read('cache', cacheId);
428:     if (cached) return cached;
429:     const result = await this.fetchObject(client, config, object);
430:     const stored = this.getStorage().files.write('cache', cacheId, result.data, result.mimeType);
431:     this.cleanupCache();
