437:     const object = this.normalizeObject(input, config);
438:     const cacheId = this.cacheId('thumb', config, object);
439:     const cached = this.getStorage().files.read('cache', cacheId);
440:     if (cached) return cached;
441:     const originalCacheId = this.cacheId('original', config, object);
442:     const original = this.getStorage().files.read('cache', originalCacheId)
443:       || await this.fetchObject(client, config, object);
444:     try {
445:       const thumbnail = await this.imageProcessor(original.data, { animated: false })
