679:     candidates.push(path.join(STATIC_DIR, normalizedPath, 'index.html'));
680:   } else {
681:     candidates.push(path.join(STATIC_DIR, normalizedPath));
682:     candidates.push(path.join(STATIC_DIR, `${normalizedPath}.html`));
683:     candidates.push(path.join(STATIC_DIR, normalizedPath, 'index.html'));
684:   }
685: 
686:   const staticDirResolved = path.resolve(STATIC_DIR) + path.sep;
687:   for (const candidate of candidates) {
688:     const resolved = path.resolve(candidate);
689:     if (!resolved.startsWith(staticDirResolved) && resolved !== staticDirResolved.slice(0, -1)) continue;
690:     if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) continue;
691:     pipeFileToResponse(res, resolved, 200, { 'Content-Type': getContentType(resolved) });
