1549: function drainQueue() {
1550:   if (isShuttingDown) return;
1551:   const maxConcurrency = getMaxServerConcurrency();
1552:   while (queue.length > 0) {
1553:     const taskId = queue[0];
1554:     const task = db.prepare('SELECT request_json FROM tasks WHERE id = ?').get(taskId);
1555:     const req = task ? JSON.parse(task.request_json) : null;
1556:     const imageSlots = req?.parallelCount || 1;
