1559:     // 自身就超过总并发，允许其独占运行（否则永远无法被调度）；其余情况一律等待
1560:     // 在飞任务腾出名额。
1561:     const fitsWithinLimit = activeCount + imageSlots <= maxConcurrency;
1562:     const oversizedTaskCanRunAlone = activeCount === 0 && imageSlots > maxConcurrency;
1563:     if (!fitsWithinLimit && !oversizedTaskCanRunAlone) break;
1564: 
1565:     queue.shift();
1566:     activeCount += imageSlots;
1567:     const runPromise = runTask(taskId).finally(() => {
1568:       activeCount -= imageSlots;
1569:       runningTaskPromises.delete(runPromise);
1570:       drainQueue();
1571:     });
1572:     runningTaskPromises.add(runPromise);
1573:   }
1574: }
