343: function consumeRateLimit(bucketKey, maxRequests, windowMs) {
344:   if (maxRequests <= 0) {
345:     return { allowed: false, retryAfterSeconds: Math.ceil(windowMs / 1000) };
346:   }
347:   const now = Date.now();
348:   const existing = rateLimitBuckets.get(bucketKey);
349:   if (!existing || now - existing.windowStart >= windowMs) {
350:     rateLimitBuckets.set(bucketKey, { windowStart: now, count: 1 });
351:     return { allowed: true, retryAfterSeconds: 0 };
352:   }
353:   if (existing.count >= maxRequests) {
354:     return { allowed: false, retryAfterSeconds: Math.max(1, Math.ceil((windowMs - (now - existing.windowStart)) / 1000)) };
355:   }
356:   existing.count += 1;
357:   return { allowed: true, retryAfterSeconds: 0 };
358: }
