665: function serveStatic(req, res, pathname) {
666:   if (!fs.existsSync(STATIC_DIR)) return false;
667:   let decodedPath;
668:   try {
669:     decodedPath = decodeURIComponent(pathname || '/');
670:   } catch {
671:     decodedPath = (pathname || '/').replace(/%(?![0-9a-fA-F]{2})/g, '');
672:   }
673:   // 路径遍历防护：规范化后检测 .. 路径段，提前拒绝
674:   const normalizedPath = path.normalize(decodedPath);
675:   if (normalizedPath.includes('..')) return false;
676: 
677:   const candidates = [];
678:   if (normalizedPath.endsWith('/') || normalizedPath.endsWith(path.sep)) {
679:     candidates.push(path.join(STATIC_DIR, normalizedPath, 'index.html'));
680:   } else {
681:     candidates.push(path.join(STATIC_DIR, normalizedPath));
682:     candidates.push(path.join(STATIC_DIR, `${normalizedPath}.html`));
683:     candidates.push(path.join(STATIC_DIR, normalizedPath, 'index.html'));
684:   }
685: 
686:   const staticDirResolved = path.resolve(STATIC_DIR) + path.sep;
687:   for (const candidate of candidates) {
688:     const resolved = path.resolve(candidate);
689:     if (!resolved.startsWith(staticDirResolved) && resolved !== staticDirResolved.slice(0, -1)) continue;
690:     if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) continue;
691:     pipeFileToResponse(res, resolved, 200, { 'Content-Type': getContentType(resolved) });
692:     return true;
693:   }
694: 
695:   const notFound = path.join(STATIC_DIR, '404.html');
696:   if (fs.existsSync(notFound)) {
697:     pipeFileToResponse(res, notFound, 404, { 'Content-Type': 'text/html; charset=utf-8' });
698:     return true;
699:   }
700:   return false;
701: }
