720:       }
721:     });
722:     req.on('end', () => {
723:       if (aborted) return;
724:       try {
725:         resolve(raw ? JSON.parse(raw) : {});
726:       } catch {
727:         reject(new Error('请求 JSON 格式无效'));
728:       }
729:     });
730:     req.on('error', reject);
731:   });
